        const wm_ptr: ?*const Lockfile.Package.WorkspaceMap = (if ((workspace_map != null)) (&workspace_map.?) else null);
        _ = try npm_lock.migratePackages(lockfile, manager, allocator, packages_properties.slice(), wm_ptr);
        _ = try npm_lock.applyRootOverrides(lockfile, manager, allocator, log, dir, abs_path);
        _ = try lockfile.resolve(log);
        _ = clearNonRegistryPlatformConstraints(lockfile);
        if (Environment.allow_assert) {
            _ = try lockfile.verifyData();
        }
        lockfile.meta_hash = try lockfile.generateMetaHash(false, lockfile.packages.len);
        return LoadResult{ .ok = .{ .lockfile = lockfile, .migrated = .npm, .loaded_from_binary_lockfile = false, .serializer_result = .{}, .format = .binary } };
}

pub fn reportedUnsupportedLockfileVersion(e: anytype) bool {
        return ((e.step == .migrating) and (((if (@typeInfo(@TypeOf(e)) == .@"enum") @intFromEnum(e) else e.value) == error.NPMLockfileVersionMismatch) or ((if (@typeInfo(@TypeOf(e)) == .@"enum") @intFromEnum(e) else e.value) == error.PnpmLockfileVersionInvalid)));
}

